// Author: MiYu. Script widget contexts, overlapping footprint ownership and real lumber lifecycle consumers.
#include "session.h"
#include "setup.h"
#include <algorithm>
#include <bit>
#include <iostream>

using namespace war3;
int wmain(int argc,wchar_t** argv) {
    try {
        if(argc!=3)throw std::runtime_error("Usage: war3_destructable_tests <data-root> <generated-map>");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto check=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};auto real=[](float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));};auto code=[&](const char* text){return vm.integer(std::bit_cast<std::int32_t>(ObjectData::code(text)));};auto& terrain=session.world()->data().terrain;WorldPoint point;bool found=false;
        for(unsigned y=8;y+8<(terrain.height-1)*4 && !found;y+=4)for(unsigned x=8;x+8<(terrain.width-1)*4 && !found;x+=4){bool clear=true;for(int dy=-4;dy<=4;++dy)for(int dx=-4;dx<=4;++dx)if(session.world()->pathMask({real(terrain.origin[0]+(x+dx)*32+16),real(terrain.origin[1]+(y+dy)*32+16)})&2)clear=false;if(clear){point={real(terrain.origin[0]+x*32+16),real(terrain.origin[1]+y*32+16)};found=true;}}check(found,"No clear source footprint test area");float x=std::bit_cast<float>(point.x.bits()),y=std::bit_cast<float>(point.y.bits());auto spawnTree=[&]{return vm.invoke("CreateDestructable",std::array{code("LTlt"),vm.real(point.x),vm.real(point.y),vm.real(real(270)),vm.real(real(1)),vm.integer(0)});};auto mask=session.world()->pathMask(point);auto first=spawnTree(),second=spawnTree();check(!vm.invoke("GetDestructableName",std::array{first}).text->starts_with("WESTRING_"),"Source destructable name was not localized");check((session.world()->pathMask(point)&2)!=0,"Created tree footprint not applied");vm.invoke("ProbeWatch",std::array{first});vm.invoke("ProbeEnumerate",std::array{vm.real(point.x),vm.real(point.y)});check(vm.global("probe_enumerated").bits==1,"Destructable filter/enum context did not reach script");auto table=vm.invoke("InitHashtable");check(vm.invoke("SaveDestructableHandle",std::array{table,vm.integer(1),vm.integer(2),first}).bits!=0 && vm.invoke("LoadDestructableHandle",std::array{table,vm.integer(1),vm.integer(2)}).bits==first.bits,"Destructable hashtable handle not preserved");
        vm.invoke("KillDestructable",std::array{first});vm.invoke("KillDestructable",std::array{first});check(vm.global("probe_deaths").bits==1 && (session.world()->pathMask(point)&2)!=0,"Repeated death event or overlapping footprint removal differs");vm.invoke("KillDestructable",std::array{second});check(session.world()->pathMask(point)==mask,"Tree removal cleared source terrain or retained obstacle");vm.invoke("DestructableRestoreLife",std::array{first,vm.real(real(50)),vm.boolean(true)});check((session.world()->pathMask(point)&2)!=0,"Restored tree did not restore footprint");vm.invoke("SetWidgetLife",std::array{first,vm.real(real(0))});check(vm.global("probe_deaths").bits==2 && session.world()->pathMask(point)==mask,"Generic widget life/death did not consume destructable state");vm.invoke("RemoveDestructable",std::array{first});check(!session.destructables().contains(first.bits),"Removed destructable remains in registry");
        auto tree=spawnTree();auto spawn=[&](const char* type){return vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000),code(type),vm.real(real(x+96)),vm.real(real(y)),vm.real(real(270))});};auto peasant=spawn("hpea");spawn("htow");check(session.harvest(peasant.bits,tree.bits),"Peasant tree order rejected");session.advance(12);auto& states=session.config().players[0].states;check(states.at(2)==10 && states.at(16)==10 && session.destructables().at(tree.bits)->life==40,"Peasant lumber did not damage tree and reach deposit");session.stopUnit(peasant.bits);auto ghoul=spawn("ugho");check(session.harvest(ghoul.bits,tree.bits),"Ghoul tree order rejected");session.advance(14);check(states.at(2)==30 && session.destructables().at(tree.bits)->life==20,"Ghoul source damage/capacity not consumed");session.stopUnit(ghoul.bits);auto wisp=spawn("ewsp");float life=session.destructables().at(tree.bits)->life;check(session.harvest(wisp.bits,tree.bits),"Wisp tree order rejected");session.advance(8.03125);check(states.at(2)==35 && session.destructables().at(tree.bits)->life==life,"Wisp damaged tree or did not credit lumber");session.stopUnit(wisp.bits);auto upgrade=ObjectData::code("Rhlh");auto existing=session.units().at(peasant.bits);check(std::find(existing->upgrades.begin(),existing->upgrades.end(),upgrade)!=existing->upgrades.end() && existing->technology.lumberCapacity==0,"Peasant missing baseline lumber research");auto place=[&](const char* type,float px,float py){return vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000),code(type),vm.real(real(px)),vm.real(real(py)),vm.real(real(270))});};auto mill=place("hlum",x+384,y+384);place("hkee",x+640,y+384);place("hcas",x+896,y+384);for(int field:{1,2})vm.invoke("SetPlayerState",std::array{vm.handle("player",0x100000),vm.handle("playerstate",field),vm.integer(10000)});check(session.researchInfo(upgrade,1).unsupported.empty(),"Lumber upgrade remains unsupported");check(session.research(mill.bits,upgrade),"Source lumber research was rejected");session.advance(60);session.advance(1);check(existing->technology.lumberCapacity==10,"Completed first level did not refresh existing peasant");auto worker=place("hpea",x+96,y);auto fresh=session.units().at(worker.bits);check(fresh->technology.lumberCapacity==10,"New peasant missed first level lumber research");vm.invoke("SetDestructableLife",std::array{tree,vm.real(real(50))});check(session.harvest(worker.bits,tree.bits),"Upgraded peasant tree order rejected");for(unsigned tick=0;tick<32*30 && fresh->gather.phase!=GatherOrder::Phase::Return;++tick)session.advance(1./32);check(fresh->gather.phase==GatherOrder::Phase::Return && fresh->carriedLumber==20,"First research level did not increase actual carried lumber to 20");auto owner1=vm.handle("player",0x100001);vm.invoke("SetUnitOwner",std::array{worker,owner1,vm.boolean(false)});check(fresh->owner==1 && fresh->technology.lumberCapacity==0 && fresh->carriedLumber==20,"Ownership refresh lost carried lumber or retained previous research");vm.invoke("RemoveUnit",std::array{worker});auto owner0=vm.handle("player",0x100000);vm.invoke("SetPlayerTechResearched",std::array{owner0,code("Rhlh"),vm.integer(2)});vm.invoke("SetPlayerTechResearched",std::array{owner0,code("Rhlh"),vm.integer(2)});check(existing->technology.lumberCapacity==20,"Second level research accumulated incorrectly");worker=place("hpea",x+96,y);fresh=session.units().at(worker.bits);check(fresh->technology.lumberCapacity==20,"New peasant missed second level lumber research");vm.invoke("SetDestructableLife",std::array{tree,vm.real(real(50))});check(session.harvest(worker.bits,tree.bits),"Second-level peasant tree order rejected");for(unsigned tick=0;tick<32*45 && fresh->gather.phase!=GatherOrder::Phase::Return;++tick)session.advance(1./32);check(fresh->gather.phase==GatherOrder::Phase::Return && fresh->carriedLumber==30,"Second research level did not increase actual carried lumber to 30");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS destructable consumers: widget events, enumeration, handles, overlap/restore and source lumber\nPASS lumber research: source production, existing/new units, two levels, capacity and ownership\n";return 0;
    }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
}
